WITH with_gaps AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) > INTERVAL '14' DAY THEN 1 ELSE 0 END AS new_group_flag FROM sessions), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT DATE_TRUNC('QUARTER', started_at) AS quarter_start, DATE_TRUNC('YEAR', started_at) AS year_start, browser, COUNT(*) FILTER (WHERE country = 'UK') AS uk_rows, MAX(started_at) AS last_started_at, MAX(started_at) AS last_started_at_2, COUNT(*) AS cnt, ROUND(SUM(new_group_flag) / NULLIF(COUNT(CASE WHEN browser = 'Firefox' THEN 1 END), 0), 2) AS new_group_flag_per_firefox FROM islands GROUP BY quarter_start, year_start, browser HAVING COUNT(*) FILTER (WHERE country = 'UK') < 1 ORDER BY new_group_flag_per_firefox DESC NULLS LAST;
